import { stringify } from 'yaml';
import { LOCK_VERSION } from '../shared/constants/sources.ts';
import type { LockedSources } from '../shared/types/source.ts';

const LOCK_HEADER = `# Generated by tunestra: the exact commits of git presets. Commit this file.
# Do not edit: run \`tunestra update\` to move presets to the latest commit of their refs.
`;

/** Sources are sorted, so that the file changes only when a commit changes. */
export function renderLock(sources: LockedSources): string {
  const entries = Object.entries(sources);
  const sortedEntries = entries.toSorted((left, right) => (left[0] < right[0] ? -1 : 1));
  const sortedSources = Object.fromEntries(sortedEntries);
  const yaml = stringify({
    version: LOCK_VERSION,
    sources: sortedSources,
  });

  return `${LOCK_HEADER}${yaml}`;
}
